import json,pathlib,random,resource,statistics,subprocess,time
import chess
import torch
from harbichess.backends.torch_backend import TorchPolicyValueBackend
from harbichess.backends.torch_network import load_weights,sha256
from harbichess.chess.actions import legal_action_indices
from harbichess.chess.encoding import BoardEncoder
root=pathlib.Path('/workspace/HarbiChess');out=root/'artifacts/ufuk-compile-20261003-v2';assert json.loads((out/'setup.json').read_text())['status']=='passed'
torch.set_num_threads(1);weights=root/'artifacts/ufuk-all-train-20261003/checkpoints/step-009250/model.safetensors'
eager=TorchPolicyValueBackend(load_weights(weights));fused=TorchPolicyValueBackend(load_weights(weights));network=fused.network
core=torch.compile(network._features,backend='inductor',fullgraph=True,dynamic=True)
def guarded(inputs,actions):
 if actions.ndim!=2 or actions.shape[0]!=inputs.shape[0] or actions.shape[1]==0:raise ValueError('invalid action dimensions')
 if torch.any(actions<0) or torch.any(actions>=network.config.policy_size):raise ValueError('invalid action bounds')
 return core(inputs,actions)
network.masked_policy_value=guarded
encoder=BoardEncoder();board=chess.Board();encoded=encoder.encode_board(board);legal=legal_action_indices(board)
probes=[]
with torch.inference_mode():
 for fen in [chess.STARTING_FEN,'r3k2r/8/8/8/8/8/8/R3K2R b KQkq - 0 1','4k3/P7/8/8/8/8/7p/4K3 w - - 0 1','4k3/8/8/3pP3/8/8/8/4K3 w - d6 0 1']:
  b=chess.Board(fen);p=encoder.encode_board(b);a=legal_action_indices(b)
  x=eager.evaluate_masked([p],[a])[0];y=fused.evaluate_masked([p],[a])[0]
  for v,w in [(x.policy_logits,y.policy_logits),(x.wdl_logits,y.wdl_logits)]:
   torch.testing.assert_close(torch.tensor(v),torch.tensor(w),atol=2e-5,rtol=2e-5)
   torch.testing.assert_close(torch.tensor(v).softmax(0),torch.tensor(w).softmax(0),atol=2e-5,rtol=2e-5)
  probes.append({'fen':fen,'status':'passed'})
 for invalid in [torch.empty((1,0),dtype=torch.long),torch.tensor([[-1]]),torch.tensor([[4672]])]:
  x=torch.zeros(1,8,8,104)
  for fn in [eager.network.masked_policy_value,guarded]:
   try:fn(x,invalid)
   except ValueError:pass
   else:raise AssertionError('malformed request accepted')
blocks=[];rng=random.Random(20261007);warm_started=time.perf_counter()
for batch in [1,8,32]:
 positions,actions=[encoded]*batch,[legal]*batch
 for backend in [eager,fused]:
  for _ in range(5):backend.evaluate_masked(positions,actions)
 for repeat in range(3):
  order=['eager','compiled'];rng.shuffle(order)
  for arm in order:
   backend=eager if arm=='eager' else fused;times=[]
   for _ in range(30):
    start=time.perf_counter();backend.evaluate_masked(positions,actions);times.append(time.perf_counter()-start)
   blocks.append({'batch':batch,'repeat':repeat,'arm':arm,'seconds':times,'positions_per_second':30*batch/sum(times)})
rows=[]
for batch in [1,8,32]:
 metrics={}
 for arm in ['eager','compiled']:
  selected=[b for b in blocks if b['batch']==batch and b['arm']==arm];times=sorted(t for b in selected for t in b['seconds'])
  metrics[arm]={'median_block_positions_per_second':statistics.median(b['positions_per_second'] for b in selected),'median_batch_ms':statistics.median(times)*1000,'p95_batch_ms':times[int(.95*(len(times)-1))]*1000}
 metrics['speedup']=metrics['compiled']['median_block_positions_per_second']/metrics['eager']['median_block_positions_per_second'];rows.append({'batch':batch,**metrics})
qualified=rows[0]['speedup']>=1.15 and all(r['speedup']>=.9 for r in rows[1:])
report={'status':'completed','qualification':qualified,'rows':rows,'blocks':blocks,'parity_probes':probes,'malformed_guard_cases':3,'weights_sha256':sha256(weights),'source_commit':subprocess.check_output(['git','rev-parse','HEAD'],cwd=root,text=True).strip(),'script_sha256':sha256(pathlib.Path(__file__)),'torch':torch.__version__,'device':'cpu','threads':1,'seed':20261007,'maxrss_kib':resource.getrusage(resource.RUSAGE_SELF).ru_maxrss,'scope':'isolated warmed backend host input/output included, encoding/search/setup excluded; no complete-game speed claim'}
p=out/'benchmark.json';assert not p.exists();p.write_text(json.dumps(report,indent=2)+'\n');print(json.dumps({'qualification':qualified,'rows':rows}))
